import{updateNavigation}from'./experience.mjs';
import{issueOrder,orderGoal,tacticalSkills}from'./tactics.mjs';
import {Game,dist} from './engine.mjs';import{SPAWNS,ROUTES,SITES,DOORS,BREAKABLE,point,floorClear,nearestFloor,findPath,terrainHeight}from'./lotus-map.mjs';
export class LotusGame extends Game{
 constructor(hero=0,difficulty='normal',seed=41029){super(hero,difficulty,seed);this.lotus=true;this.mode='moba';this.navigationEnabled=true;this.width=this.heightBound=160;this.sites=SITES;this.gates=DOORS.map(g=>({...g,open:false,manualUntil:Infinity,closeAt:0}));this.walls=[{...BREAKABLE}];this.platforms=[];this.zip=[[142.9,39.5],[143,52]];this.orbs=[{...nearestFloor(point('A Root')),ready:0},{...nearestFloor(point('C Mound')),ready:0}];
 for(const e of this.entities){if(e.kind==='hero'){e.r=.5;Object.assign(e,this.spawnPoint(e));}if(e.kind==='core')Object.assign(e,this.base(e.team),{r:1.6});if(e.kind==='tower'){const names=e.team===0?(e.tier===2?['A Lobby','B Pillars','C Lobby']:['A Root','B Main','C Mound']):(e.tier===2?['A Site','B Upper','C Site']:['A Tree','B Site','C Main']);Object.assign(e,nearestFloor(point(names[e.lane]),.7),{r:1});}}
 const camps=this.entities.filter(e=>e.kind==='camp');['A Rubble','A Lobby','C Mound','C Link','B Upper'].forEach((name,i)=>{const p=nearestFloor(point(name),.7);Object.assign(camps[i],p,{home:p,r:.9});});}
 base(team){return nearestFloor(SPAWNS[team],.7);}
 laneRoute(lane){return ROUTES[lane];}
 spawnPoint(e){if(e.kind==='camp')return e.home;const b=SPAWNS[e.team];return nearestFloor({x:b.x+((e.slot||0)-2)*1.7,z:b.z+(e.team?2:-2)},.5);}
 minionSpawn(team,lane,i){const b=SPAWNS[team];return nearestFloor({x:b.x+(lane-1)*1.2,z:b.z+(team?1:-1)*(i+1)*1.1},.4);}
 obstacles(team){return[...this.gates.filter(g=>!g.open),...this.walls.filter(w=>w.hp>0),...this.effects.filter(e=>e.type==='barrier'&&e.team!==team)];}
 blocked(x,z,r=.5,team=0){return !floorClear(x,z,Math.max(.03,Math.min(r,.55)-.02))||this.obstacles(team).some(o=>Math.abs(x-o.x)<o.w/2+r&&Math.abs(z-o.z)<o.h/2+r);}
 stepAllowed(){return true;}
 height(e){return terrainHeight(e.x,e.z);}
 path(a,b){return findPath(this,a,b);}
 navigate(e,target,dt){target=nearestFloor(target,Math.min(e.r,.49));const clear=()=>{const n=Math.ceil(dist(e,target)/.3);for(let i=1;i<=n;i++)if(this.blocked(e.x+(target.x-e.x)*i/n,e.z+(target.z-e.z)*i/n,e.r,e.team))return false;return true;};if(this.los(e,target)&&clear()){this.move(e,target.x-e.x,target.z-e.z,dt);e.path=null;return;}if(!e.path||this.time>(e.pathAt||0)+2||dist(e.pathGoal||target,target)>5||e.navVersion!==this.navVersion){e.path=this.path(e,target);e.pathAt=this.time;e.pathGoal={x:target.x,z:target.z};e.navVersion=this.navVersion;}while(e.path.length&&dist(e,e.path[0])<.25)e.path.shift();const p=e.path[0];if(p)this.move(e,p.x-e.x,p.z-e.z,dt);}
 command(kind){return issueOrder(this,kind);}
 ai(e,dt){const goal=e.kind==='hero'&&!e.player?orderGoal(this,e):null;if(!goal||e.dead||e.hp<e.maxHp*.25||this.status(e,'stun'))return super.ai(e,dt);const target=this.target(e,this.attackRange(e));tacticalSkills(this,e,target);if(target){e.task='集火目标';this.attack(e);return;}e.task='执行指挥';if(dist(e,goal)>4)this.navigate(e,goal,dt);}
 interact(e){for(const g of this.gates)if(!e.dead&&dist(e,g)<6){g.open=true;g.closeAt=this.time+8;this.navVersion++;this.emit('gate',{x:g.x,z:g.z,open:true});return true;}if(!e.dead&&dist(e,{x:this.zip[0][0],z:this.zip[0][1]})<3){e.zip={a:{x:e.x,z:e.z},b:nearestFloor({x:this.zip[1][0],z:this.zip[1][1]}),t:0};this.emit('notice',{text:'A Drop · 静音单向落差'});return true;}if(dist(e,{x:this.zip[1][0],z:this.zip[1][1]})<3){this.emit('notice',{text:'A Drop为单向落差，需经A楼梯返回'});return false;}return super.interact(e);}
 separateUnits(dt){const units=this.entities.filter(e=>!e.dead&&['hero','minion'].includes(e.kind));for(let i=0;i<units.length;i++)for(let j=i+1;j<units.length;j++){const a=units[i],b=units[j];if(a.team!==b.team)continue;let dx=b.x-a.x,dz=b.z-a.z,d=Math.hypot(dx,dz);const gap=a.r+b.r+.35;if(d>=gap)continue;if(d<.001){dx=Math.sin(a.id*2.4);dz=Math.cos(a.id*2.4);d=1;}const push=Math.min(.15,(gap-Math.min(d,gap))*dt*4);for(const [e,sign]of[[a,-1],[b,1]]){if(e.player||e.channeling||e.zip)continue;const x=e.x+dx/d*push*sign,z=e.z+dz/d*push*sign;if(!this.blocked(x,z,e.r,e.team)){e.x=x;e.z=z;}}}}
 update(dt,input){if(this.mode==='moba')updateNavigation(this);super.update(dt,input);for(const g of this.gates)if(g.open&&g.closeAt&&this.time>=g.closeAt){g.open=false;g.closeAt=0;this.navVersion++;this.emit('gate',{x:g.x,z:g.z,open:false});for(const e of this.entities)if(!e.dead&&Math.abs(e.x-g.x)<g.w/2+e.r&&Math.abs(e.z-g.z)<g.h/2+e.r)Object.assign(e,nearestFloor({x:e.x+(e.x<g.x?-2:2),z:e.z+(e.z<g.z?-2:2)},e.r));}for(const e of this.entities)if(e.kind==='minion')e.r=.4;this.separateUnits(dt);}
}
